package com.aliothmoon.maafw.once;
import org.junit.Test;
import static org.junit.Assert.*;
public final class OwnTaskHandoffTest {
 @Test public void moveReturnAloneNeverReady(){OwnTaskHandoff.State s=new OwnTaskHandoff.State();s.start();assertTrue(s.arm());assertFalse(s.moved());assertFalse(s.hidden());assertTrue(s.stop());assertTrue(s.hidden());assertFalse(s.stop());assertFalse(s.moved());}
 @Test public void stopBeforeMoveReturnRequiresBoth(){OwnTaskHandoff.State s=new OwnTaskHandoff.State();s.start();s.arm();assertFalse(s.stop());assertFalse(s.hidden());assertTrue(s.moved());assertTrue(s.hidden());}
 @Test public void earlierStopCannotBeReused(){OwnTaskHandoff.State s=new OwnTaskHandoff.State();s.start();s.stop();assertFalse(s.arm());s.start();assertTrue(s.arm());assertFalse(s.moved());assertFalse(s.hidden());assertTrue(s.stop());}
 @Test public void reentryInvalidationSticky(){OwnTaskHandoff.State s=new OwnTaskHandoff.State();s.start();s.arm();s.moved();s.stop();assertTrue(s.start());assertFalse(s.hidden());assertFalse(s.stop());assertFalse(s.arm());assertFalse(s.moved());}
 @Test public void reentryBeforeStopRejects(){OwnTaskHandoff.State s=new OwnTaskHandoff.State();s.start();s.arm();assertTrue(s.start());s.moved();assertFalse(s.stop());assertFalse(s.hidden());}
 @Test public void destroyCancelMoveFailureCannotBeRevived(){for(int i=0;i<3;i++){OwnTaskHandoff.State s=new OwnTaskHandoff.State();s.start();s.arm();assertTrue(s.revoke());assertFalse(s.revoke());assertFalse(s.moved());assertFalse(s.stop());assertFalse(s.hidden());}}
 @Test public void staleInstanceCannotOpenReplacement(){OwnTaskHandoff.State old=new OwnTaskHandoff.State(), fresh=new OwnTaskHandoff.State();old.start();old.arm();old.revoke();fresh.start();assertFalse(old.stop());assertFalse(old.moved());assertFalse(fresh.hidden());}
 @Test public void exactTaskShapeOnly(){assertTrue(OwnTaskHandoff.shape(1,7,7,1,true,true,true));assertFalse(OwnTaskHandoff.shape(2,7,7,1,true,true,true));assertFalse(OwnTaskHandoff.shape(1,7,8,1,true,true,true));assertFalse(OwnTaskHandoff.shape(1,7,7,2,true,true,true));assertFalse(OwnTaskHandoff.shape(1,7,7,1,false,true,true));assertFalse(OwnTaskHandoff.shape(1,7,7,1,true,false,true));assertFalse(OwnTaskHandoff.shape(1,7,7,1,true,true,false));assertFalse(OwnTaskHandoff.shape(1,-1,-1,1,true,true,true));}
 @Test public void allSixteenCoarsePatternsRejectReadiness(){for(int bits=0;bits<16;bits++){RewardsObservation o=RewardsObservation.classify((bits&1)!=0,(bits&2)!=0,(bits&4)!=0,(bits&8)!=0);assertEquals(TargetPageReadiness.Decision.REJECT_OWN_UI,TargetPageReadiness.evaluate(o,false));TargetPageReadiness.Decision d=TargetPageReadiness.evaluate(o,true);assertNotNull(d);assertTrue(TargetPageReadiness.report(o,true).contains("拒绝业务规划和执行"));assertFalse(TargetPageReadiness.report(o,true).contains("Flow:"));if(o.page()==RewardsObservation.Page.REWARDS_HOME)assertEquals(TargetPageReadiness.Decision.NOT_ESTABLISHED,d);}}
 @Test public void nullConflictSigninUnknownRejected(){assertEquals(TargetPageReadiness.Decision.REJECT_UNRECOGNIZED,TargetPageReadiness.evaluate(null,true));assertEquals(TargetPageReadiness.Decision.REJECT_CONFLICT,TargetPageReadiness.evaluate(RewardsObservation.classify(true,true,true,false),true));assertEquals(TargetPageReadiness.Decision.REJECT_SIGN_IN,TargetPageReadiness.evaluate(RewardsObservation.classify(true,true,false,false),true));assertEquals(TargetPageReadiness.Decision.REJECT_UNRECOGNIZED,TargetPageReadiness.evaluate(RewardsObservation.classify(false,false,false,false),true));}
}
